def execute(filters=None):
    frappe.log_error("Ejecutando el reporte", "DEBUG Survey Report")

    filters = filters or {}
    survey_name = filters.get('survey')
    if not survey_name:
        return [], []

    try:
        survey_doc = frappe.get_doc("Survey", survey_name)
    except Exception:
        frappe.throw(f"Encuesta no encontrada: {survey_name}")

    survey_json = getattr(survey_doc, "survey_json", "{}") or "{}"
    question_map = get_question_labels(survey_json)

    # 2) Columnas (dinámicas)
    columns = [
        {"label": "Usuario", "fieldname": "user", "fieldtype": "Data", "width": 150},
    ]
    for qid, title in question_map.items():
        columns.append({
            "label": title,
            "fieldname": qid,
            "fieldtype": "Data",
            "width": 300
        })

    responses = frappe.get_all(
        "Survey Response",
        filters={"survey": survey_name},
        fields=["name", "owner"]
    )

    data = []
    for r in responses:
        row = {"user": r.owner}
        try:
            doc = frappe.get_doc("Survey Response", r.name)
        except Exception:
            doc = None

        raw = {}
        if doc:
            if getattr(doc, "response_json", None):
                raw = doc.response_json
          

        try:
            if isinstance(raw, str):
                parsed = json.loads(raw)
            else:
                parsed = raw or {}
        except Exception:
            parsed = {}

        for qid in question_map.keys():
            value = ""
            if isinstance(parsed, dict):
                value = parsed.get(qid, "")
            row[qid] = value
        data.append(row)

    return columns, data


def get_question_labels(survey_json):
    try:
        data = json.loads(survey_json) if isinstance(survey_json, str) else survey_json
    except Exception:
        return {}

    mapping = {}
    for page in data.get("pages", []):
        for element in page.get("elements", []):
            name = element.get("name") 
            title = element.get("title") 
            if name:
                mapping[name] = title
    return mapping
